--
-- Name: payroll_staff_filter_parameters_view; Type: VIEW; Schema: public; Owner: admin
--

CREATE VIEW public.payroll_staff_filter_parameters_view AS
 SELECT employment.payroll_staff_id,
    workload.hours AS workload_value,
    count(DISTINCT lang.id) AS professional_language_count,
    count(DISTINCT family_burden.id) AS children_count,
    EXTRACT(year FROM age((CURRENT_DATE)::timestamp with time zone, (employment.start_date)::timestamp with time zone)) AS employment_start_date_years,
    professional.payroll_instruction_degree_id AS instruction_degree,
    employment.payroll_position_type_id AS position_type,
    staff.payroll_license_degree_id AS license_degree,
    study.profession_id AS profession,
    socioeconomic.marital_status_id AS marital_status,
    employment_position.payroll_position_id AS "position",
    employment.department_id AS department,
    employment.payroll_staff_type_id AS staff_type,
    employment.payroll_contract_type_id AS contract_type
   FROM (((((((((public.payroll_employments employment
     JOIN public.payroll_employment_payroll_position employment_position ON (((employment_position.payroll_employment_id = employment.id) AND (employment_position.active = true))))
     LEFT JOIN public.payroll_workload_positions workload_position ON ((workload_position.payroll_position_id = employment_position.payroll_position_id)))
     LEFT JOIN public.payroll_workloads workload ON ((workload.id = workload_position.payroll_workload_id)))
     LEFT JOIN public.payroll_professionals professional ON ((professional.payroll_staff_id = employment.payroll_staff_id)))
     LEFT JOIN public.payroll_lang_prof lang ON ((lang.payroll_prof_id = professional.id)))
     LEFT JOIN public.payroll_staffs staff ON ((staff.id = employment.payroll_staff_id)))
     LEFT JOIN public.payroll_socioeconomics socioeconomic ON ((socioeconomic.payroll_staff_id = employment.payroll_staff_id)))
     LEFT JOIN public.payroll_family_burdens family_burden ON (((family_burden.payroll_socioeconomic_id = socioeconomic.id) AND (family_burden.payroll_relationships_id = ( SELECT payroll_relationships.id
           FROM public.payroll_relationships
          WHERE ((payroll_relationships.name)::text = 'Hijo(a)'::text)
         LIMIT 1)) AND (family_burden.deleted_at IS NULL))))
     LEFT JOIN public.payroll_studies study ON ((study.payroll_professional_id = professional.id)))
  GROUP BY employment.payroll_staff_id, workload.hours, employment.start_date, professional.payroll_instruction_degree_id, employment.payroll_position_type_id, staff.payroll_license_degree_id, study.profession_id, socioeconomic.marital_status_id, employment_position.payroll_position_id, employment.department_id, employment.payroll_staff_type_id, employment.payroll_contract_type_id;


ALTER TABLE public.payroll_staff_filter_parameters_view OWNER TO admin;

--
-- Name: compare_parameter_function(character varying, character varying, character varying, public.payroll_staff_filter_parameters_view, integer, integer); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.compare_parameter_function(p_group_type character varying, p_parameter_value character varying, p_parameter_type character varying, p_staff_row public.payroll_staff_filter_parameters_view, p_staff_years integer, p_staff_apn_years integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
            DECLARE
                v_clean_value TEXT;
                v_field_name TEXT;
                v_staff_value TEXT;
                v_json_value JSONB;
                v_from_value TEXT;
                v_to_value TEXT;        
            BEGIN
                v_clean_value := REGEXP_REPLACE(p_parameter_value, '^"|"$', '', 'g');
                v_field_name := LOWER(p_group_type);

                -- Si el group_by es 'range', procesamos el valor como JSON
                IF p_parameter_type = 'range' THEN
                    -- Convertir el valor del parámetro a JSONB y Extraer 'from' y 'to' del JSON
                    BEGIN
                        v_json_value := p_parameter_value::JSONB;
                        v_from_value := (jsonb_extract_path_text(v_json_value, 'from'))::TEXT;
                        v_to_value := (jsonb_extract_path_text(v_json_value, 'to'))::TEXT;
                        IF v_field_name = 'start_date' THEN
                            v_staff_value := p_staff_years::TEXT;
                        ELSEIF v_field_name = 'start_apn' THEN
                            v_staff_value := p_staff_apn_years::TEXT;
                        ELSE
                            BEGIN
                                EXECUTE format('SELECT ($1).%I::text', v_field_name)
                                USING p_staff_row
                                INTO v_staff_value;
                            EXCEPTION
                                WHEN undefined_column THEN
                                    RETURN FALSE;
                                WHEN OTHERS THEN
                                    RETURN FALSE;
                            END;
                        END IF;
                    END;
                ELSE
                    BEGIN
                        IF v_field_name = 'start_date' THEN
                            v_staff_value := p_staff_years::TEXT;
                        ELSEIF v_field_name = 'start_apn' THEN
                            v_staff_value := p_staff_apn_years::TEXT;
                        ELSE
                            BEGIN
                                EXECUTE format('SELECT ($1).%I::text', v_field_name)
                                USING p_staff_row
                                INTO v_staff_value;
                            EXCEPTION
                                WHEN undefined_column THEN
                                    RETURN FALSE;
                                WHEN OTHERS THEN
                                    RETURN FALSE;
                            END;
                        END IF;
                    END;
                END IF;

                IF p_parameter_type = 'range' THEN
                    IF v_staff_value::NUMERIC BETWEEN v_from_value::NUMERIC AND v_to_value::NUMERIC THEN
                        RETURN TRUE;
                    ELSE
                        RETURN FALSE;
                    END IF;
                ELSE
                    RETURN v_clean_value = v_staff_value;
                END IF;
            END;
            $_$;


ALTER FUNCTION public.compare_parameter_function(p_group_type character varying, p_parameter_value character varying, p_parameter_type character varying, p_staff_row public.payroll_staff_filter_parameters_view, p_staff_years integer, p_staff_apn_years integer) OWNER TO admin;

--
-- Name: filter_payroll_staff_children(integer, integer, date); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.filter_payroll_staff_children(current_staff_id integer, concept_id integer, period_end date) RETURNS TABLE(children_count integer)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        _son_relationship_id int;
        _option_max_date date;
        _option_min_date date;
        _option_min_val numeric;
        _option_max_val numeric;
        _value jsonb;
    BEGIN
        _son_relationship_id := (
            SELECT id 
            FROM payroll_relationships 
            WHERE name = 'Hijo(a)' 
            LIMIT 1
        );

        _value := (
            SELECT value 
            FROM payroll_concept_assign_options 
            WHERE value IS NOT NULL 
                AND applicable_id = concept_id 
                AND applicable_type = 'Modules\Payroll\Models\PayrollConcept'
        );

        _option_min_val := _value->>'minimum';
        _option_max_val := _value->>'maximum';

        _option_max_date := period_end - make_interval(years => _option_min_val::int);
        _option_min_date := period_end - make_interval(years => _option_max_val::int + 1) + interval '1 day';

        RETURN QUERY SELECT COUNT(DISTINCT pfb.id)::integer AS children_count
        FROM payroll_socioeconomics psec
        JOIN payroll_family_burdens pfb
        ON psec.id = pfb.payroll_socioeconomic_id
        WHERE psec.payroll_staff_id = current_staff_id
            AND pfb.payroll_relationships_id = _son_relationship_id
            AND pfb.birthdate IS NOT NULL
            AND pfb.birthdate
                BETWEEN _option_min_date::date AND _option_max_date::date
            AND psec.deleted_at IS NULL
            AND pfb.deleted_at IS NULL;
    END;
    $$;


ALTER FUNCTION public.filter_payroll_staff_children(current_staff_id integer, concept_id integer, period_end date) OWNER TO admin;

--
-- Name: get_expanded_formula(text); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.get_expanded_formula(f text) RETURNS text
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    nueva_formula text := f;
                    coincidencia text[];
                    concepto_id int;
                    parametro_id text;
                    subformula text;
                    param_value text;
                BEGIN
                    -- Primero expandimos todos los concept(ID)
                    LOOP
                        SELECT regexp_match(nueva_formula, 'concept\((\d+)\)') INTO coincidencia;
                        EXIT WHEN coincidencia IS NULL;

                        concepto_id := coincidencia[1]::int;

                        SELECT formula INTO subformula
                        FROM payroll_concepts
                        WHERE id = concepto_id;

                        IF subformula IS NULL THEN
                            EXIT;
                        END IF;

                        subformula := get_expanded_formula(subformula);

                        nueva_formula := regexp_replace(
                            nueva_formula,
                            'concept\(' || concepto_id || '\)',
                            '(' || subformula || ')',
                            'g'
                        );
                    END LOOP;

                    RETURN nueva_formula;
                END;
                $$;


ALTER FUNCTION public.get_expanded_formula(f text) OWNER TO admin;

--
-- Name: get_parameter_value(text, integer, date, date, integer, integer, jsonb, integer); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.get_parameter_value(param_name text, payroll_staff_id integer, period_start date, period_end date, institution_id integer, payroll_id integer, resettable_vars jsonb DEFAULT '{}'::jsonb, concept_id integer DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    param_json JSONB;
    param_type TEXT;
    result NUMERIC := 0;
    formula_text TEXT;
    key TEXT;
    time_data JSONB;
BEGIN
    SELECT p_value::jsonb INTO param_json
    FROM parameters
    WHERE p_key = param_name;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    param_type := param_json ->> 'parameter_type';

    CASE param_type
        WHEN 'global_value' THEN
            -- Verificar si el campo "percentage" es true
            IF (param_json ->> 'percentage')::BOOLEAN THEN
                result := COALESCE((param_json ->> 'value')::NUMERIC, 0) / 100;
            ELSE
                result := COALESCE((param_json ->> 'value')::NUMERIC, 0);
            END IF;

        WHEN 'resettable_variable' THEN
            BEGIN
                -- Buscar el valor en la columna payroll_parameters
                SELECT COALESCE(
                    (SELECT (param->>'value')::NUMERIC
                    FROM (
                        -- Prioridad 1: concept_id = INT y staff_id = INT (evitando cadenas vacías)
                        SELECT param
                        FROM jsonb_array_elements(
                            (SELECT payroll_parameters
                            FROM payrolls
                            WHERE id = payroll_id)::JSONB
                        ) AS param
                        WHERE NULLIF(param->>'concept_id', '')::INT = concept_id
                        AND NULLIF(param->>'staff_id', '')::INT = payroll_staff_id

                        UNION ALL
                        -- Prioridad 2: concept_id ("" o no definido)
                        SELECT param
                        FROM jsonb_array_elements(
                            (SELECT payroll_parameters
                            FROM payrolls
                            WHERE id = payroll_id)::JSONB
                        ) AS param
                        WHERE NULLIF(param->>'staff_id', '')::INT = payroll_staff_id
                        AND (param->>'concept_id' IS NULL OR param->>'concept_id' = '')

                        UNION ALL
                        -- Prioridad 3: Sin concept_id ni staff_id (NULL/cadena vacía)
                        SELECT param
                        FROM jsonb_array_elements(
                            (SELECT payroll_parameters
                            FROM payrolls
                            WHERE id = payroll_id)::JSONB
                        ) AS param
                        WHERE (param->>'concept_id' IS NULL OR param->>'concept_id' = '')
                        AND (param->>'staff_id' IS NULL OR param->>'staff_id' = '')
                    ) AS filtered_params
                    LIMIT 1
                    ),
                    0
                ) INTO result;

                -- Si no se encuentra el valor, asignar 0
                IF NOT FOUND THEN
                    result := 0;
                END IF;
            END;

        WHEN 'processed_variable' THEN
            formula_text := param_json ->> 'formula';
            result := process_parameter_formula(formula_text, payroll_staff_id, period_start, period_end, institution_id, payroll_id, resettable_vars);

        WHEN 'time_parameter' THEN
            DECLARE
                acronym TEXT;
                param_name TEXT;
                search_key TEXT;
                time_sheet_value NUMERIC;
            BEGIN
                -- Obtener el acronym y el name del parámetro desde param_json
                acronym := param_json ->> 'acronym';
                param_name := param_json ->> 'name';

                -- Construir la clave que se buscará en el JSON
                search_key := acronym || ' - ' || param_name || '-' || payroll_staff_id;

                DECLARE
                    row RECORD; -- Variable para almacenar cada fila devuelta por la consulta
                    time_sheet_value NUMERIC := 0; -- Inicializar el valor como 0
                BEGIN
                    -- Iterar sobre cada fila devuelta por la consulta
                    FOR row IN
                        SELECT time_sheet_data
                        FROM payroll_time_sheets
                        WHERE from_date >= period_start
                        AND (to_date IS NULL OR to_date <= period_end)
                        AND document_status_id = (
                            SELECT id
                            FROM document_status
                            WHERE action = 'CE'
                        )
                    LOOP
                        -- Convertir time_sheet_data a JSONB y buscar la clave
                        IF row.time_sheet_data::JSONB ? search_key THEN
                            time_sheet_value := (row.time_sheet_data::JSONB ->> search_key)::NUMERIC;
                            EXIT; -- Salir del bucle una vez encontrado
                        END IF;
                    END LOOP;

                    -- Asignar el valor encontrado a result
                    result := COALESCE(time_sheet_value, 0);
                END;
            END;
        ELSE
            result := 0;
    END CASE;

    BEGIN
        EXECUTE 'SELECT ' || result;
    EXCEPTION
        WHEN OTHERS THEN
            -- Capturar cualquier excepción y asignar 0 al resultado
            result := 0;
    END;

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_parameter_value(param_name text, payroll_staff_id integer, period_start date, period_end date, institution_id integer, payroll_id integer, resettable_vars jsonb, concept_id integer) OWNER TO admin;

--
-- Name: get_staff_start_apn_function(integer[], date, date); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.get_staff_start_apn_function(payroll_staff_ids integer[], period_start date, period_end date) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
            BEGIN
                RETURN ARRAY(
                    SELECT ARRAY[
                        employment.payroll_staff_id,
                        -- Sumar los años de servicio en la institución actual y en otras instituciones públicas
                        EXTRACT(YEAR FROM AGE(period_start, employment.start_date))::INTEGER +
                        COALESCE((
                            SELECT SUM(EXTRACT(YEAR FROM AGE(
                                COALESCE(previous_jobs.end_date, period_start), -- Usar period_start si end_date es NULL
                                previous_jobs.start_date
                            )))::INTEGER
                            FROM payroll_previous_jobs AS previous_jobs
                            JOIN payroll_sector_types AS sector_types
                                ON previous_jobs.payroll_sector_type_id = sector_types.id
                            WHERE previous_jobs.payroll_employment_id = employment.id
                            AND previous_jobs.deleted_at IS NULL
                            AND sector_types.name = 'Público'
                        ), 0) -- Si no hay registros, sumar 0
                    ]
                    FROM payroll_employments AS employment
                    WHERE employment.payroll_staff_id = ANY (payroll_staff_ids)
                );
            END;
            $$;


ALTER FUNCTION public.get_staff_start_apn_function(payroll_staff_ids integer[], period_start date, period_end date) OWNER TO admin;

--
-- Name: get_staff_start_date_function(integer[], date, date); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.get_staff_start_date_function(payroll_staff_ids integer[], period_start date, period_end date) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
            BEGIN
                RETURN ARRAY(
                    SELECT ARRAY[
                        employment.payroll_staff_id,
                        EXTRACT(YEAR FROM AGE(period_start, employment.start_date))::INTEGER
                    ]
                    FROM payroll_employments AS employment
                    WHERE employment.payroll_staff_id = ANY (payroll_staff_ids)
                );
            END;
            $$;


ALTER FUNCTION public.get_staff_start_date_function(payroll_staff_ids integer[], period_start date, period_end date) OWNER TO admin;

--
-- Name: payroll_staff_assign_to_function(integer, jsonb, date, date); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.payroll_staff_assign_to_function(p_concept_id integer, p_filters jsonb, p_period_start date, p_period_end date) RETURNS TABLE(staff_id integer, staff_name character varying)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        _is_restrict BOOLEAN;
        -- Variables para opciones específicas (se llenarán desde la tabla temporal)
        _option_ids INT[];
        _option_value JSONB;
        _option_min_val NUMERIC;
        _option_max_val NUMERIC;
        _option_min_date DATE;
        _option_max_date DATE;

        _active_filters TEXT[];
        _excluded_ids INT[]; -- Para 'staff_except_specified'

        _sql_where_conditions TEXT[];
        _final_where_clause TEXT := '';
        _base_sql TEXT;
        _rule_condition TEXT;
        _rule_id TEXT;
        _rule_definition JSONB;
        _rule_type TEXT;

        _son_relationship_id INT;
        _retired_inactivity_type_id INT;

    BEGIN
        -- 1. Crear Tabla Temporal para Opciones de Asignación
        --    Se elimina automáticamente al final de la transacción/función
        CREATE TEMP TABLE temp_assign_options (
            key TEXT,
            assignable_id INT,
            value JSONB
        ) ON COMMIT DROP;

        -- 2. Obtener 'is_restrict' del Concepto
        SELECT pc.is_strict INTO _is_restrict
        FROM payroll_concepts pc
        WHERE pc.id = p_concept_id AND pc.deleted_at IS NULL;

        IF NOT FOUND THEN RAISE EXCEPTION 'Concepto % no encontrado', p_concept_id; END IF;

        -- 3. Poblar la Tabla Temporal con Opciones de Asignación
        INSERT INTO temp_assign_options (key, assignable_id, value)
        SELECT key, assignable_id::INT, to_jsonb(value) -- Convertir 'value' a JSONB
        FROM payroll_concept_assign_options
        WHERE applicable_type = 'Modules\Payroll\Models\PayrollConcept'
        AND applicable_id = p_concept_id
        AND deleted_at IS NULL;

        -- 4. Extraer filtros activos del PARÁMETRO p_filters
        SELECT array_agg(item->>'id') INTO _active_filters
        FROM jsonb_array_elements(p_filters) item;
        _active_filters := COALESCE(_active_filters, '{}');

        -- 5. Extraer Exclusiones DESDE temp_assign_options, SI la regla está activa
        IF 'staff' = ANY(_active_filters) THEN
            SELECT array_agg(tao.assignable_id) INTO _excluded_ids
            FROM temp_assign_options tao
            WHERE tao.key = 'staff' AND tao.assignable_id IS NOT NULL;
        END IF;
        _excluded_ids := COALESCE(_excluded_ids, '{}');

        RAISE NOTICE 'Concept ID: %, Is Restrict: %, Filters Input: %, Exceptions Param: %',
                    p_concept_id, _is_restrict, _active_filters, _excluded_ids;

        -- 6. Manejo de Casos Especiales ('all', 'staff') si NO es restringido
        IF NOT _is_restrict THEN
            IF 'staff' = ANY(_active_filters) THEN
                RAISE NOTICE 'Regla STAFF encontrada (no restringido).';
                RETURN QUERY SELECT ps.id, CONCAT(ps.first_name, ' ', ps.last_name) FROM payroll_staffs ps WHERE ps.id = ANY(_excluded_ids) AND ps.deleted_at IS NULL ORDER BY ps.first_name, ps.last_name;
                RETURN;
            END IF;
            IF 'all' = ANY(_active_filters) THEN
                RAISE NOTICE 'Regla ALL encontrada (no restringido).';
                RETURN QUERY SELECT ps.id, CONCAT(ps.first_name, ' ', ps.last_name) FROM payroll_staffs ps WHERE EXISTS (SELECT 1 FROM payroll_employments pe WHERE pe.payroll_staff_id = ps.id AND pe.active = TRUE AND pe.deleted_at IS NULL) AND ps.deleted_at IS NULL ORDER BY ps.first_name, ps.last_name;
                RETURN;
            END IF;
        END IF;

        -- 7. Construir Cláusula WHERE
        _sql_where_conditions := '{}';

        _son_relationship_id := (SELECT id FROM payroll_relationships WHERE name = 'Hijo(a)' LIMIT 1);
        IF _son_relationship_id IS NULL THEN _son_relationship_id := 3; END IF;
        _retired_inactivity_type_id := (SELECT id FROM payroll_inactivity_types WHERE name ILIKE 'jubilado' LIMIT 1);


        -- Iterar sobre los filtros ACTIVOS PASADOS COMO PARÁMETRO
        FOR _rule_definition IN SELECT * FROM jsonb_array_elements(p_filters) LOOP
            _rule_id := _rule_definition->>'id';
            IF _rule_id IN ('all', 'staff', 'staff_except_specified') THEN CONTINUE; END IF;

            IF _rule_definition IS NULL THEN RAISE WARNING 'Definición regla % no encontrada.', _rule_id; CONTINUE; END IF;
            _rule_type := _rule_definition->>'type';

            -- Resetear y extraer opciones para la regla actual DESDE temp_assign_options
            _option_ids := NULL; _option_value := NULL; _option_min_val := NULL; _option_max_val := NULL; _option_min_date := NULL; _option_max_date := NULL;
            _rule_condition := NULL;

            IF _rule_type = 'list' THEN
                SELECT array_agg(tao.assignable_id) INTO _option_ids
                FROM temp_assign_options tao
                WHERE tao.key = _rule_id AND tao.assignable_id IS NOT NULL;
                _option_ids := COALESCE(_option_ids, '{}');
            ELSIF _rule_type = 'range' THEN
                SELECT tao.value INTO _option_value
                FROM temp_assign_options tao
                WHERE tao.key = _rule_id AND tao.value IS NOT NULL LIMIT 1;
                IF _option_value IS NOT NULL THEN
                    IF _option_value->>'minimum' IS NOT NULL THEN
                        _option_min_val := (_option_value->>'minimum')::NUMERIC;
                    END IF;
                    IF _option_value->>'maximum' IS NOT NULL THEN
                        _option_max_val := (_option_value->>'maximum')::NUMERIC;
                    END IF;
                END IF;
            END IF;

            CASE _rule_id
                WHEN 'all_active_staff' THEN
                    _rule_condition := 'EXISTS (
                        SELECT 1
                        FROM payroll_employments pe
                        WHERE pe.payroll_staff_id = ps.id
                            AND pe.active = TRUE
                            AND pe.deleted_at IS NULL
                    )';

                WHEN 'staff_with_sons_has_scholarships' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_socioeconomics psec
                                JOIN payroll_family_burdens pfb
                                    ON psec.id = pfb.payroll_socioeconomic_id
                                WHERE psec.payroll_staff_id = ps.id
                                    AND pfb.payroll_relationships_id = %L
                                    AND pfb.has_scholarships = TRUE
                                    AND pfb.payroll_scholarship_types_id = ANY(%L::int[])
                                    AND psec.deleted_at IS NULL AND pfb.deleted_at IS NULL
                            )',
                            _son_relationship_id, _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                WHEN 'all_staff_with_sons' THEN
                    IF _option_min_val IS NOT NULL AND _option_max_val IS NOT NULL THEN
                        _option_max_date := p_period_end - make_interval(years => _option_min_val::int);
                        _option_min_date := p_period_end - make_interval(years => _option_max_val::int + 1) + interval '1 day';
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_socioeconomics psec
                                JOIN payroll_family_burdens pfb
                                ON psec.id = pfb.payroll_socioeconomic_id
                                WHERE psec.payroll_staff_id = ps.id
                                    AND pfb.payroll_relationships_id = %L
                                    AND pfb.birthdate IS NOT NULL
                                    AND pfb.birthdate
                                        BETWEEN %L::date AND %L::date
                                    AND psec.deleted_at IS NULL
                                    AND pfb.deleted_at IS NULL
                            )',
                            _son_relationship_id, _option_min_date, _option_max_date
                        );
                    ELSE RAISE WARNING 'Regla % sin rango.', _rule_id; END IF;

                WHEN 'all_staff_with_sons_studying' THEN
                    _rule_condition := format(
                        'EXISTS (
                            SELECT 1
                            FROM payroll_socioeconomics psec
                            JOIN payroll_family_burdens pfb
                            ON psec.id = pfb.payroll_socioeconomic_id
                            WHERE psec.payroll_staff_id = ps.id
                                AND pfb.payroll_relationships_id = %L
                                AND pfb.is_student = TRUE
                                AND psec.deleted_at IS NULL
                                AND pfb.deleted_at IS NUL
                        )',
                        _son_relationship_id
                    );

                WHEN 'all_survivor_staff' THEN
                    _rule_condition := format(
                        'WHERE ps.has_died = TRUE
                        AND EXISTS (
                            SELECT 1 FROM
                            payroll_survivors psv
                                WHERE psv.payroll_staff_id = ps.id
                                    AND psv.first_name IS NOT NULL
                                    AND psv.last_name IS NOT NULL
                                    AND psv.payroll_staff_id IS NOT NULL
                                    AND psv.id_number IS NOT NULL
                                    AND psv.finance_bank_id IS NOT NULL
                                    AND psv.finance_account_type_id IS NOT NULL
                                    AND psv.payroll_account_number IS NOT NULL
                                    AND psv.deleted_at IS NULL
                        )
                        AND EXISTS (
                            SELECT 1
                            FROM payroll_employments pe
                            WHERE pe.payroll_staff_id = ps.id
                                AND pe.payroll_inactivity_type_id = %L
                                AND pe.active = TRUE
                                AND pe.deleted_at IS NULL
                        )',
                        _retired_inactivity_type_id
                    );

                WHEN 'all_staff_who_belong_to_a_workers_union' THEN
                    _rule_condition := 'EXISTS (
                        SELECT 1
                        FROM payroll_employments pe
                        WHERE pe.payroll_staff_id = ps.id
                            AND pe.workers_union = TRUE
                            AND pe.active = TRUE
                            AND pe.deleted_at IS NULL
                        )';

                WHEN 'all_staff_affiliated_with_the_savings_fund' THEN
                    _rule_condition := 'EXISTS (
                        SELECT 1
                        FROM payroll_employments pe
                        WHERE pe.payroll_staff_id = ps.id
                            AND pe.savings_fund = TRUE
                            AND pe.active = TRUE
                            AND pe.deleted_at IS NULL
                        )';

                WHEN 'staff_according_position' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_employments pe
                                JOIN payroll_employment_payroll_position pe_pp
                                    ON pe.id = pe_pp.payroll_employment_id
                                JOIN payroll_positions pp
                                    ON pe_pp.payroll_position_id = pp.id
                                WHERE pe.payroll_staff_id = ps.id
                                    AND pe.active = TRUE
                                    AND pe_pp.active = TRUE
                                    AND pe_pp.payroll_position_id = ANY(%L::int[])
                                    AND pe.deleted_at IS NULL
                                    AND pp.deleted_at IS NULL
                            )',
                            _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                WHEN 'all_staff_not_in_vacation' THEN
                    IF p_period_start IS NOT NULL AND p_period_end IS NOT NULL THEN
                        _rule_condition := format(
                            'NOT EXISTS (
                                SELECT 1
                                FROM payroll_vacation_requests pvr
                                WHERE pvr.payroll_staff_id = ps.id
                                    AND pvr.status = %L::text
                                    AND pvr.start_date <= %L::date
                                    AND pvr.end_date >= %L::date
                                    AND pvr.deleted_at IS NULL
                            )',
                            'approved', p_period_end, p_period_start
                        );
                    ELSE RAISE WARNING 'Regla % requiere fechas.', _rule_id; END IF;

                WHEN 'all_staff_vacation_return' THEN
                    IF p_period_start IS NOT NULL AND p_period_end IS NOT NULL THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_vacation_requests pvr_option_value
                                WHERE pvr.payroll_staff_id = ps.id
                                    AND pvr.status = ''approved''
                                    AND pvr.end_date >= %L::date
                                    AND pvr.end_date <= %L::date
                                    AND pvr.deleted_at IS NULL
                                )',
                                p_period_start, p_period_end
                            );
                    ELSE RAISE WARNING 'Regla % requiere fechas.', _rule_id; END IF;

                WHEN 'all_disabled_staff' THEN
                    _rule_condition := 'WHERE ps.has_disability = TRUE';

                WHEN 'all_except_disabled_staff' THEN
                    _rule_condition := 'WHERE ps.has_disability = FALSE';

                WHEN 'all_studying_staff' THEN
                    _rule_condition := 'EXISTS (
                        SELECT 1
                        FROM payroll_professionals pp
                        WHERE pp.payroll_staff_id = ps.id
                            AND pp.is_student = TRUE
                            AND pp.deleted_at IS NULL
                        )';

                WHEN 'staff_master_the_languages' THEN
                    _rule_condition := '(
                        SELECT count(*)
                        FROM payroll_professionals pp
                        JOIN payroll_language_payroll_professional pl_pp
                            ON pp.id = pl_pp.payroll_professional_id
                        WHERE pp.payroll_staff_id = ps.id
                            AND pp.deleted_at IS NULL
                            AND pl.deleted_at IS NUL
                        ) > 1';

                WHEN 'staff_according_contract_type' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_employments pe
                                WHERE pe.payroll_staff_id = ps.id
                                    AND pe.active = TRUE
                                    AND pe.payroll_contract_type_id = ANY(%L::int[])
                                    AND pe.deleted_at IS NULL
                            )',
                            _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                WHEN 'staff_according_department' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_employments pe
                                WHERE pe.payroll_staff_id = ps.id
                                    AND pe.active = TRUE
                                    AND pe.department_id = ANY(%L::int[])
                                    AND pe.deleted_at IS NULL
                            )',
                            _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                WHEN 'staff_according_position_type' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_employments pe
                                WHERE pe.payroll_staff_id = ps.id
                                    AND pe.active = TRUE
                                    AND pe.payroll_position_type_id = ANY(%L::int[])
                                    AND pe.deleted_at IS NULL
                            )',
                            _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                WHEN 'staff_according_staff_type' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1 
                                FROM payroll_employments pe
                                WHERE pe.payroll_staff_id = ps.id 
                                    AND pe.active = TRUE 
                                    AND pe.payroll_staff_type_id = ANY(%L::int[]) 
                                    AND pe.deleted_at IS NULL
                            )',
                            _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                    WHEN 'all_staff_according_start_date' THEN
                        -- Primera consulta: Buscar solo por pe.start_date <= %L::date si _option_max_val no es NULL
                        IF _option_max_val IS NOT NULL THEN
                            -- Calcular la fecha límite restando años de p_period_end_option_max_date
                            _option_max_date := p_period_end - make_interval(years => _option_max_val::int);

                            -- Construir la condición SQL para la primera consulta
                            _rule_condition := format(
                                'EXISTS (
                                    SELECT 1
                                    FROM payroll_employments pe
                                    WHERE pe.payroll_staff_id = ps.id
                                    AND pe.active = TRUE
                                    AND pe.start_date <= %L::date
                                    AND pe.deleted_at IS NULL
                                )',
                                _option_max_date
                            );
                        ELSE
                            RAISE WARNING 'Regla % sin max (years).', _rule_id;
                        END IF;

                        -- Segunda consulta: Agregar condición adicional si p_period_start y p_period_end no son NULL
                        IF p_period_start IS NOT NULL AND p_period_end IS NOT NULL THEN
                            -- Construir la condición SQL para la segunda consulta
                            _rule_condition := _rule_condition || format(
                                ' AND (
                                    -- Caso 1: Período dentro del mismo año
                                    to_char(pe.start_date, ''MM-DD'') BETWEEN %L AND %L
                                    -- Caso 2: Período cruza el límite de un año
                                    OR to_char(pe.start_date, ''MM-DD'') BETWEEN %L AND ''12-31''
                                    OR to_char(pe.start_date, ''MM-DD'') BETWEEN ''01-01'' AND %L
                                )',
                                to_char(p_period_start, 'MM-DD'),
                                to_char(p_period_end, 'MM-DD'),
                                to_char(p_period_start, 'MM-DD'),
                                to_char(p_period_end, 'MM-DD')
                            );
                        ELSE
                            RAISE WARNING 'Regla % requiere fechas de período.', _rule_id;
                        END IF;

                WHEN 'staff_according_instruction_degree' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'EXISTS (
                                SELECT 1
                                FROM payroll_professionals pp
                                WHERE pp.payroll_staff_id = ps.id
                                    AND pp.payroll_instruction_degree_id = ANY(%L::int[])
                                    AND pp.deleted_at IS NULL
                            )',
                            _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                WHEN 'staff_according_gender' THEN
                    IF array_length(_option_ids, 1) > 0 THEN
                        _rule_condition := format(
                            'WHERE ps.payroll_gender_id = ANY(%L::int[])'
                            , _option_ids
                        );
                    ELSE RAISE WARNING 'Regla % sin IDs.', _rule_id; END IF;

                ELSE RAISE WARNING 'Regla % no implementada.', _rule_id;
            END CASE;

            -- Añadir condición válida al array, asegurando chequeo de activo si es necesario
            IF _rule_condition IS NOT NULL THEN
                IF _rule_id NOT IN ('all_survivor_staff', 'all_disabled_staff', 'all_except_disabled_staff', 'staff_according_gender') AND _rule_condition NOT LIKE '%pe.active = TRUE%' THEN
                    _rule_condition := '(' || _rule_condition || ')
                        AND EXISTS (
                            SELECT 1 FROM
                            payroll_employments pe
                            WHERE pe.payroll_staff_id = ps.id
                                AND pe.active = TRUE
                                AND pe.deleted_at IS NULL
                        )';
                END IF;
                _sql_where_conditions := array_append(_sql_where_conditions, '(' || _rule_condition || ')');
            END IF;

        END LOOP; -- Fin del bucle de filtros activos

        -- 7. Combinar condiciones y añadir exclusiones/condición base activa
        _base_sql := 'SELECT ps.id::INT AS staff_id, ps.first_name as staff_name
            FROM payroll_staffs ps
            WHERE ps.deleted_at IS NULL '; -- Base soft delete check

        IF array_length(_sql_where_conditions, 1) > 0 THEN
            IF _is_restrict THEN
                _final_where_clause := ' AND ' || array_to_string(_sql_where_conditions, ' AND ');
            ELSE
                _final_where_clause := ' AND (' || array_to_string(_sql_where_conditions, ' OR ') || ')';
            END IF;
            _base_sql := _base_sql || _final_where_clause;

        ELSE
            -- Casos donde el bucle no generó condiciones (basado en filtros de entrada)
            IF 'staff' = ANY(_active_filters) AND _is_restrict THEN
                _base_sql := _base_sql || format(' AND ps.id = ANY(%L::int[])', _excluded_ids);
            ELSIF 'all' = ANY(_active_filters) AND _is_restrict THEN
                _base_sql := _base_sql || ' AND EXISTS (SELECT 1 FROM payroll_employments pe WHERE pe.payroll_staff_id = ps.id AND pe.active = TRUE AND pe.deleted_at IS NULL)';
            ELSIF NOT ('staff' = ANY(_active_filters) OR 'all' = ANY(_active_filters)) THEN
                -- Si no hay reglas válidas (ni 'all' ni 'staff') y el bucle no generó nada, nadie cumple
                _base_sql := _base_sql || ' AND FALSE ';
            -- Si era 'staff' o 'all' pero _is_restrict=false, ya se retornó antes.
            END IF;
        END IF;

        -- Aplicar exclusión 'staff_except_specified' si la regla estaba activa y se encontraron IDs
        IF 'staff_except_specified' = ANY(_active_filters) AND array_length(_excluded_ids, 1) > 0 THEN
            _base_sql := _base_sql || format(' AND ps.id <> ALL (%L::int[]) ', _excluded_ids);
        END IF;

        _base_sql := _base_sql || ' ORDER BY ps.first_name, ps.last_name;';

        RAISE NOTICE 'SQL Final: %', _base_sql;

        -- 8. Ejecutar y Devolver
        RETURN QUERY EXECUTE _base_sql;
        RETURN;

    EXCEPTION
        WHEN others THEN
            RAISE WARNING 'Error en payroll_staff_assign_to_function: % - SQLSTATE: %', SQLERRM, SQLSTATE;
            RETURN;
    END;
    $$;


ALTER FUNCTION public.payroll_staff_assign_to_function(p_concept_id integer, p_filters jsonb, p_period_start date, p_period_end date) OWNER TO admin;

--
-- Name: payroll_staff_tabulators_function(integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.payroll_staff_tabulators_function(p_staff_id integer, p_tabulator_id integer, staff_institution_years integer, staff_apn_years integer, period_start date, period_end date) RETURNS TABLE(staff_id integer, t_tabulator_id integer, vertical_scale_group_by text, vertical_scale_type text, horizontal_scale_group_by text, horizontal_scale_type text, scale_value numeric, tipo_coincidencia text)
    LANGUAGE plpgsql IMMUTABLE
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    psfpv.payroll_staff_id::INT,
                    ptv.tabulator_id::INT,
                    ptv.vertical_scale_group_by::TEXT,
                    ptv.vertical_scale_type::TEXT,
                    ptv.horizontal_scale_group_by::TEXT,
                    ptv.horizontal_scale_type::TEXT,
                    ptv.scale_value::NUMERIC,
                    CASE
                        WHEN ptv.tabulator_id IS NULL THEN 'Sin coincidencia'
                        WHEN compare_parameter_function(ptv.vertical_scale_group_by, ptv.parameter_vertical_value, ptv.vertical_scale_type, psfpv, staff_institution_years, staff_apn_years)
                            AND compare_parameter_function(ptv.horizontal_scale_group_by, ptv.parameter_horizontal_value, ptv.horizontal_scale_type, psfpv, staff_institution_years, staff_apn_years)
                            THEN 'Coincidencia completa'
                        WHEN compare_parameter_function(ptv.vertical_scale_group_by, ptv.parameter_vertical_value, ptv.vertical_scale_type, psfpv, staff_institution_years, staff_apn_years)
                            THEN 'Coincidencia vertical'
                        WHEN compare_parameter_function(ptv.horizontal_scale_group_by, ptv.parameter_horizontal_value, ptv.horizontal_scale_type, psfpv, staff_institution_years, staff_apn_years)
                            THEN 'Coincidencia horizontal'
                        ELSE CONCAT('Sin coincidencia (V:', COALESCE(ptv.vertical_scale_group_by, 'NULL'), ', H:', COALESCE(ptv.horizontal_scale_group_by, 'NULL'), ')')
                    END AS tipo_coincidencia
                FROM 
                    payroll_staff_filter_parameters_view AS psfpv
                LEFT JOIN
                    payroll_tabulators_function(period_start, period_end) AS ptv ON TRUE
                LEFT JOIN
                    payroll_salary_adjustments AS psa ON psa.payroll_salary_tabulator_id = ptv.tabulator_id
                WHERE
                    (compare_parameter_function(ptv.vertical_scale_group_by, ptv.parameter_vertical_value, ptv.vertical_scale_type, psfpv, staff_institution_years, staff_apn_years)
                    OR
                    compare_parameter_function(ptv.horizontal_scale_group_by, ptv.parameter_horizontal_value, ptv.horizontal_scale_type, psfpv, staff_institution_years, staff_apn_years))
                    AND p_staff_id = psfpv.payroll_staff_id
                    AND p_tabulator_id = ptv.tabulator_id;
            END;
            $$;


ALTER FUNCTION public.payroll_staff_tabulators_function(p_staff_id integer, p_tabulator_id integer, staff_institution_years integer, staff_apn_years integer, period_start date, period_end date) OWNER TO admin;

--
-- Name: payroll_tabulators_function(date, date); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.payroll_tabulators_function(period_start date, period_end date) RETURNS TABLE(tabulator_id integer, tabulator_name character varying, tabulator_type character varying, percentage boolean, horizontal_scale_name character varying, horizontal_scale_type character varying, horizontal_scale_group_by character varying, vertical_scale_name character varying, vertical_scale_type character varying, vertical_scale_group_by character varying, institution_id integer, institution_acronym character varying, institution_name character varying, currency_name character varying, currency_decimal_places integer, currency_symbol character varying, scale_id integer, scale_value numeric, parameter_horizontal_name character varying, parameter_horizontal_value text, parameter_vertical_name character varying, parameter_vertical_value text)
    LANGUAGE plpgsql IMMUTABLE
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    tabulators.id::INT AS tabulator_id,
                    tabulators.name AS tabulator_name,
                    tabulators.payroll_salary_tabulator_type AS tabulator_type,
                    tabulators.percentage AS percentage,
                    horizontal_scales.name AS horizontal_scale_name,
                    horizontal_scales.type AS horizontal_scale_type,
                    horizontal_scales.group_by AS horizontal_scale_group_by,
                    vertical_scales.name AS vertical_scale_name,
                    vertical_scales.type AS vertical_scale_type,
                    vertical_scales.group_by AS vertical_scale_group_by,
                    institutions.id::INT AS institution_id,
                    institutions.acronym AS institution_acronym,
                    institutions.name AS institution_name,
                    currencies.name AS currency_name,
                    currencies.decimal_places AS currency_decimal_places,
                    currencies.symbol AS currency_symbol,
                    scales.id::INT AS scale_id,
                    CASE
                        WHEN psa.increase_of_type = 'absolute_value' AND tabulators.percentage IS FALSE THEN (scales.value + psa.value)::NUMERIC
                        WHEN psa.increase_of_type = 'percentage' AND tabulators.percentage IS FALSE THEN (scales.value + ((scales.value * psa.value) / 100))::NUMERIC
                        WHEN psa.increase_of_type = 'different' AND tabulators.percentage IS FALSE THEN (
                            SELECT 
                                CAST(NULLIF(salary->>'value', '') AS NUMERIC)
                            FROM jsonb_array_elements(psa.salary_values::JSONB) AS salary
                            WHERE salary->>'id' = scales.id::TEXT
                        )::NUMERIC
                        WHEN psa.increase_of_type = 'absolute_value' AND tabulators.percentage IS TRUE THEN ((scales.value + psa.value) / 100)::NUMERIC
                        WHEN psa.increase_of_type = 'percentage' AND tabulators.percentage IS TRUE THEN ((scales.value + ((scales.value * psa.value) / 100)) / 100)::NUMERIC
                        WHEN psa.increase_of_type = 'different' AND tabulators.percentage IS TRUE THEN (
                            SELECT 
                                CAST(NULLIF(salary->>'value', '') AS NUMERIC) / 100
                            FROM jsonb_array_elements(psa.salary_values::JSONB) AS salary
                            WHERE salary->>'id' = scales.id::TEXT
                        )::NUMERIC
                        ELSE
                            CASE
                                WHEN tabulators.percentage IS FALSE THEN scales.value::NUMERIC
                                ELSE (scales.value / 100)::NUMERIC
                            END
                    END AS scale_value,
                    psh.name AS parameter_horizontal_name,
                    psh.value AS parameter_horizontal_value,
                    psv.name AS parameter_vertical_name,
                    psv.value AS parameter_vertical_value
                FROM
                    payroll_salary_tabulators AS tabulators
                JOIN
                    payroll_salary_tabulator_scales AS scales
                    ON scales.payroll_salary_tabulator_id = tabulators.id
                    AND scales.deleted_at IS NULL
                JOIN
                    institutions
                    ON institutions.id = tabulators.institution_id AND institutions.deleted_at IS NULL
                LEFT JOIN
                    currencies
                    ON currencies.id = tabulators.currency_id AND currencies.deleted_at IS NULL
                LEFT JOIN
                    payroll_salary_scales AS horizontal_scales
                    ON horizontal_scales.id = tabulators.payroll_horizontal_salary_scale_id
                    AND horizontal_scales.deleted_at IS NULL
                LEFT JOIN
                    payroll_scales AS psh
                    ON psh.id = scales.payroll_horizontal_scale_id
                    AND psh.deleted_at is NULL
                LEFT JOIN payroll_salary_scales AS vertical_scales
                    ON vertical_scales.id = tabulators.payroll_vertical_salary_scale_id
                    AND vertical_scales.deleted_at IS NULL
                LEFT JOIN
                    payroll_scales AS psv
                    ON psv.id = scales.payroll_vertical_scale_id
                    AND psv.deleted_at is NULL
                LEFT JOIN
                    payroll_salary_adjustments AS psa
                    ON psa.payroll_salary_tabulator_id = tabulators.id
                    AND start_increase_date >= period_start
                    AND (end_increase_date <= period_end OR end_increase_date IS NULL)
                WHERE
                    tabulators.deleted_at IS NULL
                    AND tabulators.active = TRUE;
            END;
            $$;


ALTER FUNCTION public.payroll_tabulators_function(period_start date, period_end date) OWNER TO admin;

--
-- Name: process_formula(integer[], integer, date, date, integer, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.process_formula(staff_ids integer[], concept_id integer, period_start date, period_end date, institution_id integer, payroll_id integer, processed_concepts jsonb DEFAULT '{}'::jsonb, resettable_vars jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(staff_id integer, staff_full_name text, staff_id_number text, instruction_degree text, staff_position text, staff_start_date date, institution_years integer, concept_type text, concept_name text, calculated_value numeric, concept_formula text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    formula_text TEXT;
    parameter RECORD;
    match TEXT;
    matches TEXT[];
    p_tabulator_id INT;
    tabulator_value NUMERIC;
    result NUMERIC := 0;
    recursive_result RECORD;
    current_staff_id INT;
    staff_start_date_years INT[];
    staff_apn_years INT[];
    start_apn_value INT := 0;
    start_date_value INT := 0;
BEGIN
    -- Obtener los start_date de los trabajadores a partir de la funcion get_staff_start_date_function
    SELECT * INTO staff_start_date_years
    FROM get_staff_start_date_function(staff_ids, period_start, period_end);

    -- Obtener los start_date de los trabajadores a partir de la funcion get_staff_start_apn_function
    SELECT * INTO staff_apn_years
    FROM get_staff_start_apn_function(staff_ids, period_start, period_end);

    -- Iterar sobre cada staff_id en el array
    FOREACH current_staff_id IN ARRAY staff_ids LOOP
        -- Obtener el nombre completo del empleado
        SELECT CONCAT_WS(' ', first_name, last_name) INTO staff_full_name
        FROM payroll_staffs
        WHERE id = current_staff_id;

        -- Obtener el nombre completo del empleado
        SELECT id_number INTO staff_id_number
        FROM payroll_staffs
        WHERE id = current_staff_id;

        -- Obtener el grado de instrucción del empleado
        SELECT name INTO instruction_degree
        FROM payroll_instruction_degrees
        WHERE id = (
            SELECT payroll_instruction_degree_id
            FROM payroll_professionals
            WHERE payroll_staff_id = current_staff_id
        );

        -- Obtener el cargo del empleado
        SELECT name INTO staff_position
        FROM payroll_positions
        WHERE id = (
            SELECT payroll_position_id
            FROM payroll_employment_payroll_position
            WHERE payroll_employment_id = (
                SELECT id FROM payroll_employments
                WHERE payroll_staff_id = current_staff_id
            )
        );

        -- Obtener la fecha de inicio en las insitución del empleado
        SELECT start_date INTO staff_start_date
        FROM payroll_employments
        WHERE payroll_staff_id = current_staff_id;

        -- Obtener fórmula
        SELECT formula INTO formula_text
        FROM payroll_concepts
        WHERE id = concept_id;

        -- Procesar llamadas a concept(...)
        matches := ARRAY(SELECT regexp_matches(formula_text, 'concept\((\d+)\)', 'g'))::TEXT[];

        IF matches IS NULL THEN
            matches := ARRAY[]::TEXT[];
        END IF;

        FOREACH match IN ARRAY matches LOOP
            SELECT * INTO recursive_result FROM process_formula(
                ARRAY[current_staff_id], -- Pasar el ID actual como un array de un solo elemento
                match::INT,
                period_start,
                period_end,
                institution_id,
                payroll_id,
                processed_concepts,
                resettable_vars
            );

            processed_concepts := jsonb_set(
                processed_concepts,
                ARRAY[match],
                to_jsonb(recursive_result.calculated_value),
                true
            );

            formula_text := REPLACE(
                formula_text,
                'concept(' || match || ')',
                recursive_result.calculated_value::TEXT
            );
        END LOOP;

        -- Obtener el valor de START_DATE desde staff_start_date_years
        DECLARE
            staff_start_dates INTEGER[][];
            pair INTEGER[];
            staff_id INT;
            years INT;
        BEGIN
            start_date_value  := 0;
            -- Iterar sobre cada subarreglo usando FOREACH con SLICE 1
            IF staff_start_date_years IS NOT NULL AND array_length(staff_start_date_years, 1) > 0 THEN

                FOREACH pair SLICE 1 IN ARRAY staff_start_date_years LOOP
                    staff_id := pair[1];
                    years := pair[2];

                    -- Realizar la validación deseada
                    IF staff_id = current_staff_id THEN
                        start_date_value := years;
                    END IF;
                END LOOP;
            END IF;

            IF POSITION('START_DATE' IN formula_text) > 0 THEN
                -- Reemplazar START_DATE en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'START_DATE',
                    COALESCE(start_date_value, 0)::TEXT
                );
            END IF;

            institution_years := COALESCE(start_date_value, 0)::INT;
        END;

        -- Reemplazar START_APN con el valor desde get_staff_start_apn_function
        -- TODO: hacer funcion para obtener el valor de START_APN
        DECLARE
            staff_start_dates INTEGER[][];
            pair INTEGER[];
            staff_id INT;
            years INT;
        BEGIN
            -- Iterar sobre cada subarreglo usando FOREACH con SLICE 1
            IF staff_apn_years IS NOT NULL AND array_length(staff_apn_years, 1) > 0 THEN
                FOREACH pair SLICE 1 IN ARRAY staff_apn_years LOOP
                    staff_id := pair[1];
                    years := pair[2];

                    -- Realizar la validación deseada
                    IF staff_id = current_staff_id THEN
                        start_apn_value := years;
                    END IF;
                END LOOP;
            END IF;

            IF POSITION('START_APN' IN formula_text) > 0 THEN
                -- Reemplazar START_DATE en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'START_APN',
                    COALESCE(start_apn_value, 0)::TEXT
                );
            END IF;
        END;

        -- Reemplazar tabuladores
        matches := ARRAY(SELECT regexp_matches(formula_text, 'tabulator\((\d+)\)', 'g'))::TEXT[];

        IF matches IS NULL THEN
            matches := ARRAY[]::TEXT[];
        END IF;

        FOREACH match IN ARRAY matches LOOP
            p_tabulator_id := match::INT;

            SELECT scale_value INTO tabulator_value
            FROM payroll_staff_tabulators_function(
                current_staff_id,
                p_tabulator_id,
                start_date_value,
                start_apn_value,
                period_start,
                period_end
            );

            formula_text := REPLACE(
                formula_text,
                'tabulator(' || p_tabulator_id || ')',
                COALESCE(tabulator_value, 0)::TEXT
            );
        END LOOP;

        -- Reemplazar parámetros tipo parameter(ID)
        matches := ARRAY(SELECT regexp_matches(formula_text, 'parameter\(([^\)]+)\)', 'g'))::TEXT[];

        IF matches IS NULL THEN
            matches := ARRAY[]::TEXT[];
        END IF;

        FOREACH match IN ARRAY matches LOOP
            -- Obtener el nombre del parámetro dentro de parameter(...)
            formula_text := REPLACE(
                formula_text,
                'parameter(' || match || ')',
                get_parameter_value('global_parameter_' || match, current_staff_id, period_start, period_end, institution_id, payroll_id, resettable_vars, concept_id)::TEXT
            );
        END LOOP;

        -- Reemplazar WORKLOAD con el valor desde payroll_workload_positions
        IF POSITION('WORKLOAD' IN formula_text) > 0 THEN
            DECLARE
                w_value NUMERIC;
            BEGIN
                -- Obtener el id de workload desde payroll_workload_positions
                SELECT workload_value
                INTO w_value
                FROM payroll_staff_filter_parameters_view
                WHERE payroll_staff_id = current_staff_id;

                -- Reemplazar WORKLOAD en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'WORKLOAD',
                    COALESCE(w_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar NUMBER_LANG con el valor desde payroll_staff_filter_parameters_view
        IF POSITION('NUMBER_LANG' IN formula_text) > 0 THEN
            DECLARE
                number_lang_value NUMERIC;
            BEGIN
                -- Obtener el valor de NUMBER_LANG desde payroll_staff_filter_parameters_view
                SELECT professional_language_count
                INTO number_lang_value
                FROM payroll_staff_filter_parameters_view
                WHERE payroll_staff_id = current_staff_id;

                -- Reemplazar NUMBER_LANG en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'NUMBER_LANG',
                    COALESCE(number_lang_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar NUMBER_CHILDREN con el valor desde payroll_staff_filter_parameters_view
        IF POSITION('NUMBER_CHILDREN' IN formula_text) > 0 THEN
            DECLARE
                number_children_value NUMERIC;
            BEGIN
                -- Obtener el valor de NUMBER_CHILDREN desde payroll_staff_filter_parameters_view
                SELECT children_count
                INTO number_children_value
                FROM filter_payroll_staff_children(current_staff_id, concept_id, period_end);

                -- Reemplazar NUMBER_CHILDREN en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'NUMBER_CHILDREN',
                    COALESCE(number_children_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar VACATION_DAYS
        IF POSITION('VACATION_DAYS' IN formula_text) > 0 OR POSITION('ADDITIONAL_DAYS_PER_YEAR' IN formula_text) > 0 THEN
            DECLARE
                additional_days_per_year_value NUMERIC;
                vacation_days_value NUMERIC;
                assign_to_value JSONB;
            BEGIN
                -- Obtener el valor de VACATION_DAYS desde payroll_vacation_policies
                SELECT additional_days_per_year, vacation_days, assign_to
                INTO additional_days_per_year_value, vacation_days_value, assign_to_value
                FROM payroll_vacation_policies
                WHERE EXISTS (
                    SELECT 1
                    FROM payroll_staff_assign_to_function(
                        concept_id,
                        (assign_to)::JSONB,
                        period_start,
                        period_end
                    ) psatf
                    WHERE psatf.staff_id = current_staff_id
                );

                -- Reemplazar ADDITIONAL_DAYS_PER_YEAR
                IF POSITION('ADDITIONAL_DAYS_PER_YEAR' IN formula_text) > 0 THEN
                    -- Reemplazar ADDITIONAL_DAYS_PER_YEAR en la fórmula
                    formula_text := REPLACE(
                        formula_text,
                        'ADDITIONAL_DAYS_PER_YEAR',
                        COALESCE(additional_days_per_year_value, 0)::TEXT
                    );    
                END IF;

                IF POSITION('VACATION_DAYS' IN formula_text) > 0 THEN
                    -- Reemplazar VACATION_DAYS en la fórmula
                    formula_text := REPLACE(
                        formula_text,
                        'VACATION_DAYS',
                        COALESCE(vacation_days_value, 0)::TEXT
                    );
                END IF;
            END;
        END IF;

        -- Reemplazar DAYS_REQUESTED
        IF POSITION('DAYS_REQUESTED' IN formula_text) > 0 THEN
            DECLARE
                days_requested_value NUMERIC;
            BEGIN
                -- Obtener el valor de DAYS_REQUESTED desde payroll_vacation_requests
                SELECT days_requested
                INTO days_requested_value
                FROM payroll_vacation_requests
                WHERE payroll_staff_id = current_staff_id;

                -- Reemplazar DAYS_REQUESTED en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'DAYS_REQUESTED',
                    COALESCE(days_requested_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar BENEFIT_DAYS
        IF POSITION('BENEFIT_DAYS' IN formula_text) > 0 THEN
            DECLARE
                benefit_days_value NUMERIC;
            BEGIN
                -- Obtener el valor de BENEFIT_DAYS desde payroll_benefits_policies
                SELECT benefit_days
                INTO benefit_days_value
                FROM payroll_benefits_policies
                WHERE active = TRUE
                AND start_date >= period_start
                AND (end_date IS NULL OR end_date <= period_end)
                AND institution_id = institution_id;

                -- Reemplazar BENEFIT_DAYS en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'BENEFIT_DAYS',
                    COALESCE(benefit_days_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar BENEFIT_ADDITIONAL_DAYS_PER_YEAR
        IF POSITION('BENEFIT_ADDITIONAL_DAYS_PER_YEAR' IN formula_text) > 0 THEN
            DECLARE
                benefit_additional_days_per_year_value NUMERIC;
            BEGIN
                -- Obtener el valor de BENEFIT_ADDITIONAL_DAYS_PER_YEAR desde payroll_benefits_policies
                SELECT additional_days_per_year
                INTO benefit_additional_days_per_year_value
                FROM payroll_benefits_policies
                WHERE active = TRUE
                AND start_date >= period_start
                AND (end_date IS NULL OR end_date <= period_end)
                AND institution_id = institution_id;

                -- Reemplazar BENEFIT_ADDITIONAL_DAYS_PER_YEAR en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'BENEFIT_ADDITIONAL_DAYS_PER_YEAR',
                    COALESCE(benefit_additional_days_per_year_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar WORK_INTERRUPTION_DAYS
        IF POSITION('WORK_INTERRUPTION_DAYS' IN formula_text) > 0 THEN
            DECLARE
                work_interruption_days_value NUMERIC;
            BEGIN
                -- Obtener el valor de WORK_INTERRUPTION_DAYS desde payroll_benefits_policies
                SELECT work_interruption_days
                INTO work_interruption_days_value
                FROM payroll_benefits_policies
                WHERE active = TRUE
                AND start_date >= period_start
                AND (end_date IS NULL OR end_date <= period_end)
                AND institution_id = institution_id;

                -- Reemplazar WORK_INTERRUPTION_DAYS en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'WORK_INTERRUPTION_DAYS',
                    COALESCE(work_interruption_days_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar MONTH_WORKED_DAYS
        IF POSITION('MONTH_WORKED_DAYS' IN formula_text) > 0 THEN
            DECLARE
                month_worked_days_value NUMERIC;
            BEGIN
                -- Obtener el valor de MONTH_WORKED_DAYS desde payroll_benefits_policies
                SELECT month_worked_days
                INTO month_worked_days_value
                FROM payroll_benefits_policies
                WHERE active = TRUE
                AND start_date >= period_start
                AND (end_date IS NULL OR end_date <= period_end)
                AND institution_id = institution_id;

                -- Reemplazar MONTH_WORKED_DAYS en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'MONTH_WORKED_DAYS',
                    COALESCE(month_worked_days_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar ari_register
        IF POSITION('ari_register' IN formula_text) > 0 THEN
            DECLARE
                ari_register_value NUMERIC;
            BEGIN
                -- Obtener el valor de ari_register desde payroll_benefits_policies
                SELECT percetage
                INTO ari_register_value
                FROM payroll_ari_registers
                WHERE payroll_staff_id = current_staff_id
                AND from_date >= period_start
                AND (to_date IS NULL OR to_date <= period_end);

                -- Reemplazar ari_register en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'ari_register',
                    COALESCE(ari_register_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar savings_fund
        IF POSITION('savings_fund' IN formula_text) > 0 THEN
            DECLARE
                savings_fund_value NUMERIC;
            BEGIN
                -- Obtener el valor de savings_fund desde payroll_benefits_policies
                SELECT percetage
                INTO savings_fund_value
                FROM payroll_savings_funds
                WHERE payroll_staff_id = current_staff_id
                AND from_date >= period_start
                AND (to_date IS NULL OR to_date <= period_end);

                -- Reemplazar savings_fund en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'savings_fund',
                    COALESCE(savings_fund_value, 0)::TEXT
                );
            END;
        END IF;

        -- Reemplazar wage_garnishment
        IF POSITION('wage_garnishment' IN formula_text) > 0 THEN
            DECLARE
                wage_garnishment_value NUMERIC;
            BEGIN
                -- Obtener el valor de wage_garnishment desde payroll_benefits_policies
                SELECT percetage
                INTO wage_garnishment_value
                FROM payroll_wage_garnishments
                WHERE payroll_staff_id = current_staff_id
                AND from_date >= period_start
                AND (to_date IS NULL OR to_date <= period_end);

                -- Reemplazar wage_garnishment en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'wage_garnishment',
                    COALESCE(wage_garnishment_value, 0)::TEXT
                );
            END;
        END IF;

        BEGIN
            EXECUTE 'SELECT ' || formula_text INTO result;
            -- Redondear el resultado a dos decimales
            result := ROUND(result, 2);
        EXCEPTION
            WHEN OTHERS THEN
                -- Capturar cualquier excepción y asignar 0 al resultado
                result := 0;
        END;

        -- Redondear los valores numéricos en formula_text a dos decimales
        formula_text := regexp_replace(
            formula_text,
            '(\d+\.\d{2})\d*',
            '\1',
            'g'
        );

        -- Devolver resultado para el staff_id actual
        RETURN QUERY SELECT 
            current_staff_id,
            staff_full_name,
            staff_id_number,
            instruction_degree,
            staff_position,
            staff_start_date,
            institution_years,
            (SELECT pt.name::TEXT FROM payroll_concepts pc JOIN payroll_concept_types pt ON pc.payroll_concept_type_id = pt.id WHERE pc.id = concept_id),
            (SELECT name::TEXT FROM payroll_concepts WHERE id = concept_id),
            result,
            formula_text::TEXT;
    END LOOP;
END;
$$;


ALTER FUNCTION public.process_formula(staff_ids integer[], concept_id integer, period_start date, period_end date, institution_id integer, payroll_id integer, processed_concepts jsonb, resettable_vars jsonb) OWNER TO admin;

--
-- Name: process_parameter_formula(text, integer, date, date, integer, integer, jsonb, integer); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.process_parameter_formula(formula_text text, current_staff_id integer, period_start date, period_end date, institution_id integer, payroll_id integer, resettable_vars jsonb DEFAULT '{}'::jsonb, concept_id integer DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    parameter RECORD;
    match TEXT;
    matches TEXT[];
    result NUMERIC := 0;
    staff_start_date_years INT[];
    staff_apn_years INT[];
BEGIN
    -- Obtener los start_date de los trabajadores a partir de la funcion get_staff_start_date_function
    SELECT * INTO staff_start_date_years
    FROM get_staff_start_date_function(ARRAY[current_staff_id], period_start, period_end);

    -- Obtener los start_date de los trabajadores a partir de la funcion get_staff_start_apn_function
    SELECT * INTO staff_apn_years
    FROM get_staff_start_apn_function(ARRAY[current_staff_id], period_start, period_end);

    -- Reemplazar parámetros tipo parameter(ID)
    matches := ARRAY(SELECT regexp_matches(formula_text, 'parameter\(([^\)]+)\)', 'g'))::TEXT[];

    IF matches IS NULL THEN
        matches := ARRAY[]::TEXT[];
    END IF;

    FOREACH match IN ARRAY matches LOOP
        -- Obtener el nombre del parámetro dentro de parameter(...)
        formula_text := REPLACE(
            formula_text,
            'parameter(' || match || ')',
            get_parameter_value('global_parameter_' || match, current_staff_id, period_start, period_end, institution_id, payroll_id, resettable_vars, concept_id)::TEXT
        );
    END LOOP;

    -- Reemplazar WORKLOAD con el valor desde payroll_workload_positions
    IF POSITION('WORKLOAD' IN formula_text) > 0 THEN
        DECLARE
            w_value NUMERIC;
        BEGIN
            -- Obtener el id de workload desde payroll_workload_positions
            SELECT workload_value
            INTO w_value
            FROM payroll_staff_filter_parameters_view
            WHERE payroll_staff_id = current_staff_id;

            -- Reemplazar WORKLOAD en la fórmula
            formula_text := REPLACE(
                formula_text,
                'WORKLOAD',
                COALESCE(w_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar NUMBER_LANG con el valor desde payroll_staff_filter_parameters_view
    IF POSITION('NUMBER_LANG' IN formula_text) > 0 THEN
        DECLARE
            number_lang_value NUMERIC;
        BEGIN
            -- Obtener el valor de NUMBER_LANG desde payroll_staff_filter_parameters_view
            SELECT professional_language_count
            INTO number_lang_value
            FROM payroll_staff_filter_parameters_view
            WHERE payroll_staff_id = current_staff_id;

            -- Reemplazar NUMBER_LANG en la fórmula
            formula_text := REPLACE(
                formula_text,
                'NUMBER_LANG',
                COALESCE(number_lang_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar NUMBER_CHILDREN con el valor desde payroll_staff_filter_parameters_view
    IF POSITION('NUMBER_CHILDREN' IN formula_text) > 0 THEN
        DECLARE
            number_children_value NUMERIC;
        BEGIN
            -- Obtener el valor de NUMBER_CHILDREN desde payroll_staff_filter_parameters_view
            SELECT children_count
            INTO number_children_value
            FROM filter_payroll_staff_children(current_staff_id, concept_id, period_end);

            -- Reemplazar NUMBER_CHILDREN en la fórmula
            formula_text := REPLACE(
                formula_text,
                'NUMBER_CHILDREN',
                COALESCE(number_children_value, 0)::TEXT
            );
        END;
    END IF;

    -- Obtener el valor de START_DATE desde staff_start_date_years
    IF POSITION('START_DATE' IN formula_text) > 0 THEN
        DECLARE
            staff_start_dates INTEGER[][];
            pair INTEGER[];
            staff_id INT;
            years INT;
            start_date_value NUMERIC := 0; -- Inicializar el valor como 0
        BEGIN
            -- Iterar sobre cada subarreglo usando FOREACH con SLICE 1
            IF staff_start_date_years IS NOT NULL AND array_length(staff_start_date_years, 1) > 0 THEN
                FOREACH pair SLICE 1 IN ARRAY staff_start_date_years LOOP
                    staff_id := pair[1];
                    years := pair[2];

                    -- Realizar la validación deseada
                    IF staff_id = current_staff_id THEN
                        start_date_value := years;
                    END IF;
                END LOOP;
            END IF;

            -- Reemplazar START_DATE en la fórmula
            formula_text := REPLACE(
                formula_text,
                'START_DATE',
                COALESCE(start_date_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar START_APN con el valor desde get_staff_start_apn_function
    -- TODO: hacer funcion para obtener el valor de START_APN
    IF POSITION('START_APN' IN formula_text) > 0 THEN
        DECLARE
            staff_start_dates INTEGER[][];
            pair INTEGER[];
            staff_id INT;
            years INT;
            start_apn_value NUMERIC := 0; -- Inicializar el valor como 0
        BEGIN
            -- Iterar sobre cada subarreglo usando FOREACH con SLICE 1
            IF staff_apn_years IS NOT NULL AND array_length(staff_apn_years, 1) > 0 THEN
                FOREACH pair SLICE 1 IN ARRAY staff_apn_years LOOP
                    staff_id := pair[1];
                    years := pair[2];

                    -- Realizar la validación deseada
                    IF staff_id = current_staff_id THEN
                        start_apn_value := years;
                    END IF;
                END LOOP;
            END IF;

            -- Reemplazar START_DATE en la fórmula
            formula_text := REPLACE(
                formula_text,
                'START_APN',
                COALESCE(start_apn_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar VACATION_DAYS
    IF POSITION('VACATION_DAYS' IN formula_text) > 0 OR POSITION('ADDITIONAL_DAYS_PER_YEAR' IN formula_text) > 0 THEN
        DECLARE
            additional_days_per_year_value NUMERIC;
            vacation_days_value NUMERIC;
            assign_to_value JSONB;
        BEGIN
            -- Obtener el valor de VACATION_DAYS desde payroll_vacation_policies
            SELECT additional_days_per_year, vacation_days, assign_to
            INTO additional_days_per_year_value, vacation_days_value, assign_to_value
            FROM payroll_vacation_policies
            WHERE EXISTS (
                SELECT 1
                FROM payroll_staff_assign_to_function(
                    concept_id,
                    (assign_to)::JSONB,
                    period_start,
                    period_end
                ) psatf
                WHERE psatf.staff_id = current_staff_id
            );

            -- Reemplazar ADDITIONAL_DAYS_PER_YEAR
            IF POSITION('ADDITIONAL_DAYS_PER_YEAR' IN formula_text) > 0 THEN
                -- Reemplazar ADDITIONAL_DAYS_PER_YEAR en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'ADDITIONAL_DAYS_PER_YEAR',
                    COALESCE(additional_days_per_year_value, 0)::TEXT
                );    
            END IF;

            IF POSITION('VACATION_DAYS' IN formula_text) > 0 THEN
                -- Reemplazar VACATION_DAYS en la fórmula
                formula_text := REPLACE(
                    formula_text,
                    'VACATION_DAYS',
                    COALESCE(vacation_days_value, 0)::TEXT
                );
            END IF;
        END;
    END IF;

    -- Reemplazar DAYS_REQUESTED
    IF POSITION('DAYS_REQUESTED' IN formula_text) > 0 THEN
        DECLARE
            days_requested_value NUMERIC;
        BEGIN
            -- Obtener el valor de DAYS_REQUESTED desde payroll_vacation_requests
            SELECT days_requested
            INTO days_requested_value
            FROM payroll_vacation_requests
            WHERE payroll_staff_id = current_staff_id;

            -- Reemplazar DAYS_REQUESTED en la fórmula
            formula_text := REPLACE(
                formula_text,
                'DAYS_REQUESTED',
                COALESCE(days_requested_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar BENEFIT_DAYS
    IF POSITION('BENEFIT_DAYS' IN formula_text) > 0 THEN
        DECLARE
            benefit_days_value NUMERIC;
        BEGIN
            -- Obtener el valor de BENEFIT_DAYS desde payroll_benefits_policies
            SELECT benefit_days
            INTO benefit_days_value
            FROM payroll_benefits_policies
            WHERE active = TRUE
            AND start_date >= period_start
            AND (end_date IS NULL OR end_date <= period_end)
            AND institution_id = institution_id;

            -- Reemplazar BENEFIT_DAYS en la fórmula
            formula_text := REPLACE(
                formula_text,
                'BENEFIT_DAYS',
                COALESCE(benefit_days_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar BENEFIT_ADDITIONAL_DAYS_PER_YEAR
    IF POSITION('BENEFIT_ADDITIONAL_DAYS_PER_YEAR' IN formula_text) > 0 THEN
        DECLARE
            benefit_additional_days_per_year_value NUMERIC;
        BEGIN
            -- Obtener el valor de BENEFIT_ADDITIONAL_DAYS_PER_YEAR desde payroll_benefits_policies
            SELECT additional_days_per_year
            INTO benefit_additional_days_per_year_value
            FROM payroll_benefits_policies
            WHERE active = TRUE
            AND start_date >= period_start
            AND (end_date IS NULL OR end_date <= period_end)
            AND institution_id = institution_id;

            -- Reemplazar BENEFIT_ADDITIONAL_DAYS_PER_YEAR en la fórmula
            formula_text := REPLACE(
                formula_text,
                'BENEFIT_ADDITIONAL_DAYS_PER_YEAR',
                COALESCE(benefit_additional_days_per_year_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar WORK_INTERRUPTION_DAYS
    IF POSITION('WORK_INTERRUPTION_DAYS' IN formula_text) > 0 THEN
        DECLARE
            work_interruption_days_value NUMERIC;
        BEGIN
            -- Obtener el valor de WORK_INTERRUPTION_DAYS desde payroll_benefits_policies
            SELECT work_interruption_days
            INTO work_interruption_days_value
            FROM payroll_benefits_policies
            WHERE active = TRUE
            AND start_date >= period_start
            AND (end_date IS NULL OR end_date <= period_end)
            AND institution_id = institution_id;

            -- Reemplazar WORK_INTERRUPTION_DAYS en la fórmula
            formula_text := REPLACE(
                formula_text,
                'WORK_INTERRUPTION_DAYS',
                COALESCE(work_interruption_days_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar MONTH_WORKED_DAYS
    IF POSITION('MONTH_WORKED_DAYS' IN formula_text) > 0 THEN
        DECLARE
            month_worked_days_value NUMERIC;
        BEGIN
            -- Obtener el valor de MONTH_WORKED_DAYS desde payroll_benefits_policies
            SELECT month_worked_days
            INTO month_worked_days_value
            FROM payroll_benefits_policies
            WHERE active = TRUE
            AND start_date >= period_start
            AND (end_date IS NULL OR end_date <= period_end)
            AND institution_id = institution_id;

            -- Reemplazar MONTH_WORKED_DAYS en la fórmula
            formula_text := REPLACE(
                formula_text,
                'MONTH_WORKED_DAYS',
                COALESCE(month_worked_days_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar ari_register
    IF POSITION('ari_register' IN formula_text) > 0 THEN
        DECLARE
            ari_register_value NUMERIC;
        BEGIN
            -- Obtener el valor de ari_register desde payroll_benefits_policies
            SELECT percetage
            INTO ari_register_value
            FROM payroll_ari_registers
            WHERE payroll_staff_id = current_staff_id
            AND from_date >= period_start
            AND (to_date IS NULL OR to_date <= period_end);

            -- Reemplazar ari_register en la fórmula
            formula_text := REPLACE(
                formula_text,
                'ari_register',
                COALESCE(ari_register_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar savings_fund
    IF POSITION('savings_fund' IN formula_text) > 0 THEN
        DECLARE
            savings_fund_value NUMERIC;
        BEGIN
            -- Obtener el valor de savings_fund desde payroll_benefits_policies
            SELECT percetage
            INTO savings_fund_value
            FROM payroll_savings_funds
            WHERE payroll_staff_id = current_staff_id
            AND from_date >= period_start
            AND (to_date IS NULL OR to_date <= period_end);

            -- Reemplazar savings_fund en la fórmula
            formula_text := REPLACE(
                formula_text,
                'savings_fund',
                COALESCE(savings_fund_value, 0)::TEXT
            );
        END;
    END IF;

    -- Reemplazar wage_garnishment
    IF POSITION('wage_garnishment' IN formula_text) > 0 THEN
        DECLARE
            wage_garnishment_value NUMERIC;
        BEGIN
            -- Obtener el valor de wage_garnishment desde payroll_benefits_policies
            SELECT percetage
            INTO wage_garnishment_value
            FROM payroll_wage_garnishments
            WHERE payroll_staff_id = current_staff_id
            AND from_date >= period_start
            AND (to_date IS NULL OR to_date <= period_end);

            -- Reemplazar wage_garnishment en la fórmula
            formula_text := REPLACE(
                formula_text,
                'wage_garnishment',
                COALESCE(wage_garnishment_value, 0)::TEXT
            );
        END;
    END IF;

    -- Evaluar fórmula final con manejo de división por cero
    BEGIN
        EXECUTE 'SELECT ' || formula_text INTO result;
    EXCEPTION
        WHEN OTHERS THEN
            -- Capturar cualquier excepción y asignar 0 al resultado
            result := 0;
    END;

    -- Devolver resultado
    RETURN result;
END;
$$;


ALTER FUNCTION public.process_parameter_formula(formula_text text, current_staff_id integer, period_start date, period_end date, institution_id integer, payroll_id integer, resettable_vars jsonb, concept_id integer) OWNER TO admin;

